package com.example.lms.quiz;
import com.example.lms.content.Content; import jakarta.persistence.*; import java.util.*;
@Entity public class Quiz { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) private Content content; @Column(nullable=false) private int durationMinutes; @OneToMany(mappedBy="quiz",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) private List<QuizQuestion> questions=new ArrayList<>(); protected Quiz(){} public Quiz(Content c,int d){content=c;durationMinutes=d;} public Long getId(){return id;} public Content getContent(){return content;} public int getDurationMinutes(){return durationMinutes;} public List<QuizQuestion> getQuestions(){return questions;} public void add(QuizQuestion q){q.setQuiz(this);questions.add(q);} }
